  --nw-color-text-disabled: var(--nw-gray-500);
  --nw-color-border: var(--nw-gray-200);
  --nw-focus-ring-color: var(--nw-blue-600);
  --nw-focus-ring-width: 2px;
  --nw-focus-ring-offset: 2px;
}
.nw-button {
  --nw-button-bg: #ffffff;
  --nw-button-text: #1f2933;
  --nw-button-border: var(--nw-color-border);
  background: var(--nw-button-bg);
  color: var(--nw-button-text);
  border: 1px solid var(--nw-button-border);
  padding: 8px 16px;
  border-radius: 6px;
  font: inherit;
  cursor: pointer;
}
.nw-button:focus {
  outline: none;
}

