solution.css:
:root {
  --nw-blue-600: #1f5ae0;
  --nw-blue-50: #eaf0fd;
  --nw-gray-200: #d9dee3;
  --nw-gray-500: #7b8794;
  --nw-color-action-bg: var(--nw-blue-600);
  --nw-color-action-bg-subtle: var(--nw-blue-50);
  --nw-color-text-disabled: var(--nw-gray-500);
  --nw-color-border: var(--nw-gray-200);
  --nw-focus-ring-color: var(--nw-blue-600);
  --nw-focus-ring-width: 2px;
  --nw-focus-ring-offset: 2px;
}
.nw-button {
  --nw-button-bg: #ffffff;
  --nw-button-text: #1f2933;
  --nw-button-border: var(--nw-color-border);
  background: var(--nw-button-bg);
  color: var(--nw-button-text);
  border: 1px solid var(--nw-button-border);
  padding: 8px 16px;
  border-radius: 6px;
  font: inherit;
  cursor: pointer;
}
.nw-button:focus-visible {
  outline: var(--nw-focus-ring-width) solid var(--nw-focus-ring-color);
  outline-offset: var(--nw-focus-ring-offset);
}
.nw-button[aria-pressed="true"] {
  --nw-button-bg: var(--nw-color-action-bg-subtle);
  --nw-button-border: var(--nw-color-action-bg);
}
.nw-button[aria-disabled="true"] {
  --nw-button-text: var(--nw-color-text-disabled);
  cursor: not-allowed;
}

solution.js:
let saves = 0;
const log = document.querySelector('#log');
const save = document.querySelector('#save');
const late = document.querySelector('#late');

save.addEventListener('click', () => {
  if (save.getAttribute('aria-disabled') === 'true') return;
  saves += 1;
  log.textContent = `Saved ${saves} times`;
});

late.addEventListener('click', () => {
  const pressed = late.getAttribute('aria-pressed') === 'true';
  late.setAttribute('aria-pressed', String(!pressed));
});
